CREATE TABLE public.simulation_wallets(user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, balance numeric(14,2) NOT NULL DEFAULT 0 CHECK(balance>=0), phone text NOT NULL DEFAULT '', upi_id text NOT NULL DEFAULT '', discoverable boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.simulation_wallets TO authenticated; GRANT ALL ON public.simulation_wallets TO service_role;
ALTER TABLE public.simulation_wallets ENABLE ROW LEVEL SECURITY;
CREATE POLICY wallet_owner_read ON public.simulation_wallets FOR SELECT TO authenticated USING(user_id=(SELECT auth.uid()));
CREATE UNIQUE INDEX simulation_phone_unique ON public.simulation_wallets(phone) WHERE phone<>'';
CREATE UNIQUE INDEX simulation_upi_unique ON public.simulation_wallets(upi_id) WHERE upi_id<>'';
CREATE TRIGGER wallet_updated BEFORE UPDATE ON public.simulation_wallets FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
INSERT INTO public.simulation_wallets(user_id) SELECT id FROM public.profiles;
CREATE FUNCTION public.create_simulation_wallet() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.simulation_wallets(user_id) VALUES(NEW.id); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.create_simulation_wallet() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER simulation_wallet_created AFTER INSERT ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.create_simulation_wallet();
ALTER TABLE public.transactions ADD COLUMN is_simulated boolean NOT NULL DEFAULT false;
ALTER TABLE public.payment_policies ADD COLUMN auto_refund_limit numeric(14,2) NOT NULL DEFAULT 0 CHECK(auto_refund_limit>=0);
CREATE TABLE public.simulation_transfers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requester_id uuid NOT NULL REFERENCES public.profiles(id), payer_id uuid NOT NULL REFERENCES public.profiles(id), recipient_id uuid NOT NULL REFERENCES public.profiles(id), amount numeric(14,2) NOT NULL CHECK(amount>0), sync_request_id uuid REFERENCES public.sync_requests(id), status text NOT NULL DEFAULT 'AWAITING_USER_AUTH' CHECK(status IN ('AWAITING_USER_AUTH','SUCCESS','CANCELLED')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(payer_id<>recipient_id));
GRANT SELECT ON public.simulation_transfers TO authenticated; GRANT ALL ON public.simulation_transfers TO service_role;
ALTER TABLE public.simulation_transfers ENABLE ROW LEVEL SECURITY;
CREATE POLICY transfer_participant_read ON public.simulation_transfers FOR SELECT TO authenticated USING((SELECT auth.uid()) IN (requester_id,payer_id,recipient_id));
CREATE TRIGGER transfer_updated BEFORE UPDATE ON public.simulation_transfers FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE UNIQUE INDEX simulation_sync_once ON public.simulation_transfers(sync_request_id) WHERE sync_request_id IS NOT NULL AND status<>'CANCELLED';
CREATE FUNCTION public.configure_simulation_wallet(p_phone text,p_upi text,p_discoverable boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF p_phone<>'' AND p_phone !~ '^[0-9]{10,15}$' THEN RAISE EXCEPTION 'Use 10 to 15 digits'; END IF; IF p_upi<>'' AND p_upi !~ '^[a-z0-9._-]+@[a-z0-9.-]+$' THEN RAISE EXCEPTION 'Invalid simulation UPI alias'; END IF; UPDATE public.simulation_wallets SET phone=p_phone,upi_id=p_upi,discoverable=p_discoverable WHERE user_id=auth.uid(); END $$;
CREATE FUNCTION public.top_up_simulation_wallet(p_amount numeric) RETURNS numeric LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b numeric; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF p_amount IS NULL OR p_amount<=0 OR p_amount>100000 OR p_amount<>round(p_amount,2) THEN RAISE EXCEPTION 'Enter 0.01 to 100000 fake rupees with at most two decimals'; END IF; UPDATE public.simulation_wallets SET balance=balance+p_amount WHERE user_id=auth.uid() AND balance+p_amount<=1000000 RETURNING balance INTO b; IF b IS NULL THEN RAISE EXCEPTION 'Fake balance limit is 1000000'; END IF; RETURN b; END $$;
CREATE FUNCTION public.search_simulation_recipient(p_query text) RETURNS TABLE(user_id uuid,name text,alias text) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; RETURN QUERY SELECT w.user_id,p.name,CASE WHEN w.upi_id=lower(trim(p_query)) THEN w.upi_id ELSE w.phone END FROM public.simulation_wallets w JOIN public.profiles p ON p.id=w.user_id WHERE w.discoverable AND w.user_id<>auth.uid() AND (w.phone=trim(p_query) AND w.phone<>'' OR w.upi_id=lower(trim(p_query)) AND w.upi_id<>'') LIMIT 2; END $$;
CREATE FUNCTION public.prepare_simulation_transfer(p_recipient uuid,p_amount numeric,p_sync uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.sync_requests; payer uuid:=auth.uid(); receiver uuid:=p_recipient; result uuid; BEGIN IF payer IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF p_amount IS NULL OR p_amount<=0 OR p_amount>100000 OR p_amount<>round(p_amount,2) THEN RAISE EXCEPTION 'Invalid fake amount'; END IF; IF NOT EXISTS(SELECT 1 FROM public.simulation_wallets WHERE user_id=p_recipient AND discoverable) THEN RAISE EXCEPTION 'Recipient unavailable'; END IF; IF p_recipient=payer THEN RAISE EXCEPTION 'Cannot pay yourself'; END IF; IF p_sync IS NOT NULL THEN SELECT * INTO s FROM public.sync_requests WHERE id=p_sync AND user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Request not found'; END IF; IF s.amount_type='FIXED' AND s.amount<>p_amount THEN RAISE EXCEPTION 'Amount must match fixed request'; END IF; IF s.max_cap IS NOT NULL AND p_amount>s.max_cap THEN RAISE EXCEPTION 'Amount exceeds cap'; END IF; IF NOT EXISTS(SELECT 1 FROM public.simulation_wallets WHERE user_id=p_recipient AND (phone=s.counterparty_address OR upi_id=lower(s.counterparty_address))) THEN RAISE EXCEPTION 'Recipient must match request'; END IF; IF s.direction='CREDIT' THEN payer:=p_recipient; receiver:=auth.uid(); END IF; END IF; INSERT INTO public.simulation_transfers(requester_id,payer_id,recipient_id,amount,sync_request_id) VALUES(auth.uid(),payer,receiver,p_amount,p_sync) RETURNING id INTO result; RETURN result; END $$;
CREATE FUNCTION public.confirm_simulation_transfer(p_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.simulation_transfers; pn text; rn text; tx uuid; rx uuid; BEGIN SELECT * INTO t FROM public.simulation_transfers WHERE id=p_id AND payer_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Only payer can confirm'; END IF; IF t.status='SUCCESS' THEN RETURN t.id; END IF; IF t.status<>'AWAITING_USER_AUTH' THEN RAISE EXCEPTION 'Request is no longer pending'; END IF; PERFORM 1 FROM public.simulation_wallets WHERE user_id IN(t.payer_id,t.recipient_id) ORDER BY user_id FOR UPDATE; IF (SELECT balance FROM public.simulation_wallets WHERE user_id=t.payer_id)<t.amount THEN RAISE EXCEPTION 'Insufficient fake balance'; END IF; UPDATE public.simulation_wallets SET balance=balance-t.amount WHERE user_id=t.payer_id; UPDATE public.simulation_wallets SET balance=balance+t.amount WHERE user_id=t.recipient_id; SELECT name INTO pn FROM public.profiles WHERE id=t.payer_id; SELECT name INTO rn FROM public.profiles WHERE id=t.recipient_id; INSERT INTO public.transactions(user_id,order_id,bank_ref,from_party,to_party,direction,source_type,amount,status,is_simulated,sync_request_id) VALUES(t.payer_id,'SIM-'||t.id||'-D','SIMULATION',pn,rn,'DEBIT',CASE WHEN t.sync_request_id IS NULL THEN 'DIRECT_PAYMENT' ELSE 'SYNC_REQUEST' END,t.amount,'SUCCESS',true,CASE WHEN t.requester_id=t.payer_id THEN t.sync_request_id ELSE NULL END) RETURNING id INTO tx; INSERT INTO public.transactions(user_id,order_id,bank_ref,from_party,to_party,direction,source_type,amount,status,is_simulated,sync_request_id) VALUES(t.recipient_id,'SIM-'||t.id||'-C','SIMULATION',pn,rn,'CREDIT',CASE WHEN t.sync_request_id IS NULL THEN 'DIRECT_PAYMENT' ELSE 'SYNC_REQUEST' END,t.amount,'SUCCESS',true,CASE WHEN t.requester_id=t.recipient_id THEN t.sync_request_id ELSE NULL END) RETURNING id INTO rx; INSERT INTO public.transaction_events(user_id,transaction_id,event) VALUES(t.payer_id,tx,'Simulated transfer confirmed; no real money moved'),(t.recipient_id,rx,'Simulated transfer received; no real money moved'); UPDATE public.simulation_transfers SET status='SUCCESS' WHERE id=t.id; RETURN t.id; END $$;
CREATE FUNCTION public.cancel_simulation_transfer(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.simulation_transfers SET status='CANCELLED' WHERE id=p_id AND auth.uid() IN(requester_id,payer_id) AND status='AWAITING_USER_AUTH'; IF NOT FOUND THEN RAISE EXCEPTION 'Pending request not found'; END IF; END $$;
REVOKE ALL ON FUNCTION public.configure_simulation_wallet(text,text,boolean),public.top_up_simulation_wallet(numeric),public.search_simulation_recipient(text),public.prepare_simulation_transfer(uuid,numeric,uuid),public.confirm_simulation_transfer(uuid),public.cancel_simulation_transfer(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.configure_simulation_wallet(text,text,boolean),public.top_up_simulation_wallet(numeric),public.search_simulation_recipient(text),public.prepare_simulation_transfer(uuid,numeric,uuid),public.confirm_simulation_transfer(uuid),public.cancel_simulation_transfer(uuid) TO authenticated;